a=s.index(' return `<details class="finding"');b=s.index("\n }).join('');openHash();",a)
s=s[:a]+''' return `<article class="finding" id="finding-${i+1}" data-topic="${topics[i]}"><div class="finding-heading"><span class="number">${String(i+1).padStart(2,'0')}</span><div><span class="topic">${names[topics[i]]}</span><h3>${esc(f.title)}</h3><p class="context">${esc(f.context)}</p></div></div><div class="finding-body"><div class="plain-number"><strong>${esc(f.number)}</strong><span>${esc(f.numberLabel)}</span></div><div class="plain-copy"><h4>What the records say</h4><p>${fmt(f.happened)}</p><h4>What this means</h4><p>${fmt(f.meaning)}</p><div class="still-unknown"><h4>What we still don’t know</h4><p>${fmt(f.unknown)}</p></div></div><p class="simple-source">${esc(f.source)}</p><details class="supporting"><summary>See the original evidence & detailed figures <span aria-hidden="true">+</span></summary><div>${parts}</div></details></div></article>`;
''' +s[b:]
s=s.replace('||teasers[i].toLowerCase().includes(term)','');s=s.replace('el.open=true;','')
(p/'app.js').write_text(s)
